package wordsearch

import (
	"errors"
)

// directions are the eight possible directions a word can be written in,
// expressed as {column, row} deltas.
var directions = [8][2]int{
	{1, 0},   // left to right
	{-1, 0},  // right to left
	{0, 1},   // top to bottom
	{0, -1},  // bottom to top
	{1, 1},   // top left to bottom right
	{1, -1},  // bottom left to top right
	{-1, 1},  // top right to bottom left
	{-1, -1}, // bottom right to top left
}

// notFound is used as the coordinates for words that cannot be located.
var notFound = [2][2]int{{-1, -1}, {-1, -1}}

// Solve takes in a list of words and a puzzle and returns a map of [2][2] int
// values of the first and last letter of each word, with coordinates given as
// {column, row}. If any word cannot be found, an error is returned and that
// word's coordinates are set to -1.
func Solve(words []string, puzzle []string) (map[string][2][2]int, error) {
	result := make(map[string][2][2]int, len(words))

	for _, word := range words {
		found := false
		for _, direction := range directions {
			if loc := find(word, puzzle, direction); loc != notFound {
				result[word] = loc
				found = true
				break
			}
		}
		if !found {
			result[word] = notFound
		}
	}

	for _, word := range words {
		if result[word] == notFound {
			return result, errors.New("word not found in puzzle")
		}
	}

	return result, nil
}

// find returns the coordinates of the first and last letter of word if it
// occurs in puzzle along the given direction, or notFound otherwise.
func find(word string, puzzle []string, direction [2]int) [2][2]int {
	if len(word) == 0 || len(puzzle) == 0 {
		return notFound
	}

	for row := 0; row < len(puzzle); row++ {
		for col := 0; col < len(puzzle[row]); col++ {
			if puzzle[row][col] != word[0] {
				continue
			}
			if matches(word, puzzle, col, row, direction) {
				return [2][2]int{
					{col, row},
					{col + direction[0]*(len(word)-1), row + direction[1]*(len(word)-1)},
				}
			}
		}
	}
	return notFound
}

// matches reports whether word occurs starting at (col, row) and proceeding in
// the given direction without leaving the puzzle.
func matches(word string, puzzle []string, col, row int, direction [2]int) bool {
	for i := 1; i < len(word); i++ {
		col += direction[0]
		row += direction[1]
		if row < 0 || row >= len(puzzle) || col < 0 || col >= len(puzzle[row]) {
			return false
		}
		if puzzle[row][col] != word[i] {
			return false
		}
	}
	return true
}

